    """Build the full MIME message bytes."""
    has_attachments = len(data["attachments"]) > 0
    boundary = "----=_Part_001"

    # Build headers
    lines = []
    lines.append("From: {}".format(data["from"]))
    to_list = ", ".join(data["to"])
    lines.append("To: {}".format(to_list))
    # Subject
    subject = data["subject"]
    try:
        subject.encode("ascii")
        lines.append("Subject: {}".format(subject))
    except UnicodeEncodeError:
        lines.append("Subject: {}".format(rfc2047_encode(subject)))
    # Date
    dt = datetime.fromtimestamp(data["date"], tz=timezone.utc)
    date_str = dt.strftime("%a, %d %b %Y %H:%M:%S +0000")
    lines.append("Date: {}".format(date_str))
    lines.append("Message-ID: {}".format(data["message_id"]))
    lines.append("MIME-Version: 1.0")

    # Header block
    header_block = "\r\n".join(lines) + "\r\n"

    if not has_attachments:
        # Single text/plain part
        header_block += "Content-Type: text/plain; charset=utf-8\r\n"
        header_block += "\r\n"
        # Body: convert \n to \r\n, ensure trailing CRLF
        body = data["body"].replace("\n", "\r\n")
        if not body.endswith("\r\n"):
            body += "\r\n"
        header_block += body
        return header_block.encode("ascii")
    else:
        # multipart/mixed
        header_block += "Content-Type: multipart/mixed; boundary=\"{}\"\r\n".format(boundary)

        msg_parts = []
        msg_parts.append(header_block)

        # Body part
        msg_parts.append("--{}\r\n".format(boundary))
        msg_parts.append("Content-Type: text/plain; charset=utf-8\r\n")
        msg_parts.append("\r\n")
        body = data["body"].replace("\n", "\r\n")
        if not body.endswith("\r\n"):
            body += "\r\n"
        msg_parts.append(body)

        # Attachment parts
        for att in data["attachments"]:
            msg_parts.append("--{}\r\n".format(boundary))
            msg_parts.append("Content-Type: {}\r\n".format(att["content_type"]))
            msg_parts.append("Content-Transfer-Encoding: base64\r\n")
            # Content-Disposition
            fname_encoded, is_encoded = rfc2231_encode_filename(att["filename"])
            if is_encoded:
                # Use RFC 2231: filename*=UTF-8''<encoded>
                fname_ascii = att["filename"].encode("ascii", errors="replace")
                fname_ascii = fname_ascii.decode("ascii", errors="replace")
                msg_parts.append("Content-Disposition: attachment; filename=\"{}\"; filename*=UTF-8''{}\r\n".format(fname_ascii, fname_encoded))
            else:
                msg_parts.append("Content-Disposition: attachment; filename=\"{}\"\r\n".format(att["filename"]))
            msg_parts.append("\r\n")
            # Base64 encode, max 76 chars per line
            raw = base64.b64decode(att["content_b64"], validate=True)
            b64 = base64.b64encode(raw).decode("ascii")
            for i in range(0, len(b64), 76):
                msg_parts.append(b64[i:i + 76] + "\r\n")

        # Closing boundary
        msg_parts.append("--{}--\r\n".format(boundary))

        return "".join(msg_parts).encode("ascii")


def main():
    try:
        raw = sys.stdin.read()
        data = json.loads(raw)
    except Exception:
        print(json.dumps({"error": "invalid_request"}))
        return

    try:
        validate_request(data)
    except (ValueError, KeyError, TypeError):
        print(json.dumps({"error": "invalid_request"}))
        return

    try:
        message_bytes = build_message(data)
    except Exception:
        print(json.dumps({"error": "invalid_request"}))
        return

    digest = hashlib.sha256(message_bytes).hexdigest()
    msg_b64 = base64.b64encode(message_bytes).decode("ascii")

    result = {
        "format": "eml",
        "message_b64": msg_b64,
        "sha256": digest
    }
    print(json.dumps(result))


if __name__ == "__main__":
    main()
